<h2 data-node-id="" class="c-heading" data-part="heading"><span class="sr-only">Cold, deep enough to swim in, and nobody watching it</span><span class="type-visual" aria-hidden="true"><svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 101.993 46.4" style="width:2.549825em"><use href="{base}/typography/3760ecaa48b01cd9d6c8.svg#word-0" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 96.524 46.4" style="width:2.4131em"><use href="{base}/typography/3760ecaa48b01cd9d6c8.svg#word-1" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 143.086 46.4" style="width:3.5771500000000005em"><use href="{base}/typography/3760ecaa48b01cd9d6c8.svg#word-2" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 41.27 46.4" style="width:1.0317500000000002em"><use href="{base}/typography/3760ecaa48b01cd9d6c8.svg#word-3" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 99.551 46.4" style="width:2.488775em"><use href="{base}/typography/3760ecaa48b01cd9d6c8.svg#word-4" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 45.254 46.4" style="width:1.1313499999999999em"><use href="{base}/typography/3760ecaa48b01cd9d6c8.svg#word-5" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 69.415 46.4" style="width:1.7353750000000001em"><use href="{base}/typography/3760ecaa48b01cd9d6c8.svg#word-6" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focusable="false" viewBox="0 0 145 46.4" style="width:3.625em"><use href="{base}/typography/3760ecaa48b01cd9d6c8.svg#word-7" width="100%" height="100%"></use></svg>{' '}<svg class="type-word" aria-hidden="true" focus